def main():
    src=Path(sys.argv[1] if len(sys.argv)>1 else 'form.zip')
    dst=Path('FORM_PC_TradeIn_FULL.zip')
    payload=json.loads(zlib.decompress(base64.b64decode(_BUNDLE)))
    changes=payload['changes']; manifest=payload['manifest']
    with zipfile.ZipFile(src,'r') as z, zipfile.ZipFile(dst,'w',compression=zipfile.ZIP_DEFLATED,compresslevel=7) as out:
        for path,expected in sorted(manifest.items()):
            if path in changes and 'new' in changes[path]:
                content=changes[path]['new'].encode('utf8')
            else:
                orig='form./form/'+path
                if orig not in z.namelist(): raise RuntimeError('Missing original file: '+path)
                content=z.read(orig)
                patch=changes.get(path)
                if patch:
                    if hashlib.sha256(content).hexdigest()!=patch['sha']:
                        raise RuntimeError('Original file mismatch: '+path)
                    lines=content.decode('utf8').splitlines(keepends=True)
                    for first,last,before,after in reversed(patch['ops']):
                        if ''.join(lines[first:last])!=before: raise RuntimeError('Patch context mismatch: '+path)
                        lines[first:last]=[after]
                    content=''.join(lines).encode('utf8')
            actual=hashlib.sha256(content).hexdigest()
            if actual!=expected: raise RuntimeError('Built file hash mismatch: '+path)
            out.writestr('form-store/'+path,content)
    print('Ready:',dst,'files:',len(manifest),'size:',dst.stat().st_size)

if __name__=='__main__': main()
